const agentOutput = $input.first().json;
const data = $('Construir prompt dinámico').first().json;

let respuesta = agentOutput.output || agentOutput.text || '';

if (!respuesta || respuesta.trim() === '' || respuesta.trim() === 'TOOL_SENT') {
  return [{ json: { enviar: false } }];
}

return [{
  json: {
    enviar: true,
    numero: data.numero,
    texto: respuesta,
    evolution_instance: data.evolution_instance,
    evolution_api_key: data.evolution_api_key
  }
}];

